⌈log2⌉2*n≡1+⌈log2⌉n : ∀ n {acc acc'} .{{_ : NonZero n}} → ⌈log2⌉ (2 * n) acc ≡ 1 + ⌈log2⌉ n acc'
1 clause(s), 3 step(s), lemmas: ceilHalfDouble

clause ⌈log2⌉2*n≡1+⌈log2⌉n (suc m) {ac} {ac'}
  goal: ⌈log2⌉ (2 * suc m) ac ≡ 1 + ⌈log2⌉ (suc m) ac'
  (where-block not taken apart)
  1. ⌈log2⌉ (2 * suc m) ac ≡ 1 + ⌈log2⌉ ⌈ 2 * suc m /2⌉ ({!!})
       by {!!}
  2. 1 + ⌈log2⌉ ⌈ 2 * suc m /2⌉ ({!!}) ≡ 1 + ⌈log2⌉ (suc m) ({!!})
       by {!!}
  3. 1 + ⌈log2⌉ (suc m) ({!!}) ≡ 1 + ⌈log2⌉ (suc m) ac'
       by {!!}

lemmas used:
  ceilHalfDouble : (n : ℕ) → ⌈ 2 * n /2⌉ ≡ n

⌈log2⌉2*n≡1+⌈log2⌉n : ∀ n {acc acc'} .{{_ : NonZero n}} → ⌈log2⌉ (2 * n) acc ≡ 1 + ⌈log2⌉ n acc'
2 clause(s), 4 step(s), lemmas: ceil2n/2≡n

clause ⌈log2⌉2*n≡1+⌈log2⌉n (suc zero) {ac} {ac'}
  goal: ⌈log2⌉ (2 * 1) ac ≡ 1 + ⌈log2⌉ 1 ac'
  (where-block not taken apart)
  1. ⌈log2⌉ (2 * suc zero) ac ≡ 1 + ⌈log2⌉ 1 (<-wellFounded 1)
       by {!!}
  2. 1 + ⌈log2⌉ 1 (<-wellFounded 1) ≡ 1 + ⌈log2⌉ (suc zero) ac'
       by {!!}

clause ⌈log2⌉2*n≡1+⌈log2⌉n (suc (suc n)) {ac} {ac'}
  goal: ⌈log2⌉ (2 * suc (suc n)) ac ≡ 1 + ⌈log2⌉ (suc (suc n)) ac'
  (where-block not taken apart)
  1. ⌈log2⌉ (2 * suc (suc n)) ac ≡ 1 + ⌈log2⌉ ⌈ 2 * suc (suc n) /2⌉ (<-wellFounded ⌈ 2 * suc (suc n) /2⌉)
       by {!!}
  2. 1 + ⌈log2⌉ ⌈ 2 * suc (suc n) /2⌉ (<-wellFounded ⌈ 2 * suc (suc n) /2⌉) ≡ 1 + ⌈log2⌉ (suc (suc n)) ac'
       by {!!}

lemmas used:
  ceil2n/2≡n : (n : ℕ) → ⌈ 2 * n /2⌉ ≡ n
